const input = $('4-SalvarSessao').first().json;
const cookies = JSON.stringify(input.cookies || []);
const localStorage = JSON.stringify(input.localStorage || {});

const code = `export default async function ({ page }) {
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  const cookies = ${cookies};
  const ls = ${localStorage};
  let debug = [];
  try {
    await page.setViewport({ width: 1280, height: 800 });
    await page.goto('https://app.cotadorsimplificado.com.br/?produto=hap', { waitUntil: 'domcontentloaded', timeout: 45000 });
    if (cookies.length > 0) await page.setCookie(...cookies);
    await page.evaluate((ls) => { for (const [k, v] of Object.entries(ls)) window.localStorage.setItem(k, v); }, ls);
    await page.reload({ waitUntil: 'domcontentloaded', timeout: 45000 });
    await w(3000);
    debug.push('pg');

    await page.evaluate(() => { const p = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29')); if(p) p.click(); });
    await w(1500);
    debug.push('pme');

    await page.waitForSelector('#id-nomelead', { timeout: 8000 });
    const n = await page.$('#id-nomelead');
    if (n) { await n.click(); await n.type('teste', { delay: 15 }); }
    debug.push('nm');

    const b1 = await page.$$('button');
    for (const btn of b1) { const i = await page.evaluate(el => { const s = window.getComputedStyle(el); return { t: el.textContent, d: s.display, v: s.visibility }; }, btn); if (i.t && i.t.includes('Avan') && i.d !== 'none' && i.v !== 'hidden') { await btn.click(); break; } }
    await w(2500);
    debug.push('av1');

    await page.waitForSelector('#cidade_nome', { timeout: 8000 });
    const c = await page.$('#cidade_nome');
    if (c) { await c.click(); await c.type('teresina', { delay: 80 }); }
    await w(1500);
    const tc = await page.evaluate(() => { for (const el of document.querySelectorAll('.clickable-element')) { if (el.textContent.trim() === 'Teresina - PI') { const r = el.getBoundingClientRect(); if (r.width > 0) return { x: r.x + r.width/2, y: r.y + r.height/2 }; } } return null; });
    if (tc) await page.mouse.click(tc.x, tc.y);
    await w(1500);
    debug.push('cid');

    try { await page.select('select.Dropdown', '"mei___empres_rio_individual"'); } catch(e) {}
    await w(1000);
    debug.push('mei');

    const b2 = await page.$$('button');
    for (const btn of b2) { const i = await page.evaluate(el => { const s = window.getComputedStyle(el); return { t: el.textContent, d: s.display, v: s.visibility }; }, btn); if (i.t && i.t.includes('Avan') && i.d !== 'none' && i.v !== 'hidden') { await btn.click(); break; } }
    await w(2500);
    debug.push('av2');

    const fx = await page.evaluate(() => { let c = 0; document.querySelectorAll('input').forEach(inp => { const r = inp.getBoundingClientRect(); const s = window.getComputedStyle(inp); if (r.width > 0 && s.display !== 'none' && !inp.id && inp.placeholder === '0' && inp.className.includes('cocys')) { inp.focus(); inp.value = '1'; inp.dispatchEvent(new Event('input', { bubbles: true })); inp.dispatchEvent(new Event('change', { bubbles: true })); c++; } }); return c; });
    await w(1000);
    debug.push('fx' + fx);

    const b3 = await page.$$('button');
    for (const btn of b3) { const i = await page.evaluate(el => { const s = window.getComputedStyle(el); return { t: el.textContent, d: s.display, v: s.visibility }; }, btn); if (i.t && i.t.includes('Avan') && i.d !== 'none' && i.v !== 'hidden') { await btn.click(); break; } }
    await w(3000);
    debug.push('av3');

    return { success: true, fase: 'FORM', debug, cookies: await page.cookies(), localStorage: ls };
  } catch (error) { return { success: false, fase: 'FORM', error: error.message, debug }; }
}`;

return [{ json: { code } }];
